        un_order_bands.order_gross_profit as order_gross_profit,
        un_order_bands.order_value_band as order_value_band,
        (case when (un_order_bands.location_id) = un_order_bands.location_id and (un_order_bands.ordered_at_day) = un_order_bands.ordered_at_day and (un_order_bands.customer_id) = un_order_bands.customer_id then 0 else 1 end) as is_first_customer
    from un_order_bands

),

agg_by_location_day as (

