        agg_by_location_day.high_value_orders as high_value_orders,
        case when agg_by_location_day.subtotal_total = 0 then 0 else agg_by_location_day.gross_profit_total / agg_by_location_day.subtotal_total end as gross_margin_pct,
        case when agg_by_location_day.orders_count = 0 then 0 else agg_by_location_day.revenue_total / agg_by_location_day.orders_count end as avg_order_value,
        case when agg_by_location_day.orders_count = 0 then 0 else agg_by_location_day.high_value_orders / agg_by_location_day.orders_count end as high_value_orders_pct
